cd /tmp/sparqltest && cat > run.js <<'EOF'
const fs = require('fs');
const oxigraph = require('oxigraph');
const store = new oxigraph.Store();
store.load(fs.readFileSync('/app/university_graph.ttl', 'utf8'), {format: 'text/turtle', base_iri: 'http://university.org/ontology/'});
const query = fs.readFileSync('/app/solution.sparql', 'utf8');
try {
  const result = store.query(query);
  for (const row of result) {
    console.log(row.get('professorName').value, '|', row.get('countries').value);
  }
} catch(e) {
  console.error('ERROR:', e.message);
  console.error(e.stack);
}
EOF
PATH=/opt/node/bin:$PATH node run.js
